create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),display_name text,xp bigint not null default 0 check(xp>=0),level integer not null default 1 check(level>=1));
create table public.daily_collections(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,date_key date not null,count integer not null check(count>=0),created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,unique(user_id,date_key));
create table public.cleanup_sessions(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,started_at timestamptz not null,ended_at timestamptz,count integer not null check(count>=0),duration_seconds integer check(duration_seconds>=0),distance_meters double precision check(distance_meters>=0),location_mode text not null check(location_mode in('none','approximate','route')),approximate_latitude double precision,approximate_longitude double precision,route_polyline text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null,deleted_at timestamptz);
create table public.session_photos(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null references public.cleanup_sessions(id) on delete cascade,storage_path text not null,photo_type text not null check(photo_type in('before','after')),width integer not null check(width>0),height integer not null check(height>0),size_bytes integer not null check(size_bytes>0 and size_bytes<=204800),created_at timestamptz not null default now(),deleted_at timestamptz,unique(session_id,photo_type));
create table public.quest_progress(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,quest_key text not null,period_key text not null,progress integer not null check(progress>=0),target integer not null check(target>0),completed_at timestamptz,claimed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null,unique(user_id,quest_key,period_key));
create table public.unlocks(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,unlock_key text not null,unlocked_at timestamptz not null,unique(user_id,unlock_key));
create table public.milestones(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,milestone_key text not null,achieved_at timestamptz not null,unique(user_id,milestone_key));
create table public.user_settings(user_id uuid primary key references auth.users(id) on delete cascade,theme_mode text not null,haptics_enabled boolean not null,sound_enabled boolean not null,reduced_motion boolean not null,selected_container_style text not null,cloud_photo_backup_enabled boolean not null,location_default_mode text not null,updated_at timestamptz not null);

alter table public.profiles enable row level security;alter table public.daily_collections enable row level security;alter table public.cleanup_sessions enable row level security;alter table public.session_photos enable row level security;alter table public.quest_progress enable row level security;alter table public.unlocks enable row level security;alter table public.milestones enable row level security;alter table public.user_settings enable row level security;
create policy profiles_owner_all on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy daily_owner_all on public.daily_collections for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy sessions_owner_all on public.cleanup_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy photos_owner_all on public.session_photos for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy quests_owner_all on public.quest_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy unlocks_owner_all on public.unlocks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy milestones_owner_all on public.milestones for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy settings_owner_all on public.user_settings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('session-photos','session-photos',false,204800,array['image/jpeg']) on conflict(id) do update set public=false,file_size_limit=204800,allowed_mime_types=array['image/jpeg'];
create policy photo_objects_read on storage.objects for select to authenticated using(bucket_id='session-photos' and (storage.foldername(name))[1]='users' and (storage.foldername(name))[2]=auth.uid()::text);
create policy photo_objects_insert on storage.objects for insert to authenticated with check(bucket_id='session-photos' and (storage.foldername(name))[1]='users' and (storage.foldername(name))[2]=auth.uid()::text and lower(storage.extension(name))='jpg');
create policy photo_objects_delete on storage.objects for delete to authenticated using(bucket_id='session-photos' and (storage.foldername(name))[1]='users' and (storage.foldername(name))[2]=auth.uid()::text);
create or replace function public.delete_own_account() returns void language plpgsql security definer set search_path=public as $$ begin delete from storage.objects where bucket_id='session-photos' and (storage.foldername(name))[2]=auth.uid()::text; delete from auth.users where id=auth.uid(); end; $$;
revoke all on function public.delete_own_account() from public;grant execute on function public.delete_own_account() to authenticated;
